import { NotFoundError, ValidationError } from "../domain/errors";
import { Product, type ProductSnapshot } from "../domain/product";
import type { ProductRepository } from "../domain/repositories";

export interface AddProductCommand {
  id: string;
  name: string;
  priceCents: number;
  initialStock: number;
}

export class CatalogueService {
  constructor(private readonly products: ProductRepository) {}

  addProduct(command: AddProductCommand): ProductSnapshot {
    if (this.products.findById(command.id)) {
      throw new ValidationError(`Product ${command.id} already exists`);
    }
    const product = new Product(
      command.id,
      command.name,
      command.priceCents,
      command.initialStock,
    );
    this.products.save(product);
    return product.toSnapshot();
  }

  listProducts(): ProductSnapshot[] {
    return this.products.findAll().map((p) => p.toSnapshot());
  }

  getProduct(id: string): ProductSnapshot {
    return this.requireProduct(id).toSnapshot();
  }

  restock(id: string, quantity: number): ProductSnapshot {
    const product = this.requireProduct(id);
    product.restock(quantity);
    this.products.save(product);
    return product.toSnapshot();
  }

  private requireProduct(id: string): Product {
    const product = this.products.findById(id);
    if (!product) throw new NotFoundError(`Product ${id} not found`);
    return product;
  }
}

